import {describe, expect, test} from 'vitest'
import {parseShard, selectShard} from './shard'

describe(parseShard, () => {
  test('parses a shard', () => {
    expect(parseShard('2/4')).toEqual({order: 2, total: 4})
  })

  test.each(['', '1', '0/4', '5/4', '1/0'])('rejects an invalid shard: %s', shard => {
    expect(() => parseShard(shard)).toThrow()
  })
})

test('selects items for a shard in their defined order', () => {
  expect(selectShard(['a', 'b', 'c', 'd', 'e', 'f'], {order: 2, total: 4})).toEqual(['b', 'f'])
})

type Shard = {
  order: number
  total: number
}

function parseShard(value: string): Shard {
  const match = /^(\d+)\/(\d+)$/.exec(value)
  if (!match) {
    throw new Error('Shard must use the <order>/<total> format')
  }

  const order = Number.parseInt(match[1], 10)
  const total = Number.parseInt(match[2], 10)
  if (order < 1 || total < 1 || order > total) {
    throw new Error('Shard order must be between 1 and the total number of shards')
  }

  return {order, total}
}

function selectShard<T>(items: Array<T>, shard: Shard): Array<T> {
  return items.filter((_, index) => index % shard.total === shard.order - 1)
}

export {parseShard, selectShard}
export type {Shard}
